import requests
import time
from datetime import datetime, timedelta
import sys

BASE_URL = "http://localhost:8000"


def wait_for_api(max_attempts=30):
    """Wait for API to be ready"""
    print("⏳ Waiting for API to be ready...")

    for i in range(max_attempts):
        try:
            response = requests.get(f"{BASE_URL}/health", timeout=5)
            if response.status_code == 200:
                print("✅ API is ready!")
                print(f"   Response: {response.json()}")
                return True
        except requests.exceptions.ConnectionError as e:
            if i == 0:
                print(f"   Connection error: {e}")
                print(f"   Make sure Docker containers are running:")
                print(f"   docker-compose ps")
        except requests.exceptions.Timeout:
            print(f"   Timeout connecting to {BASE_URL}")
        except Exception as e:
            print(f"   Error: {e}")

        time.sleep(1)
        if (i + 1) % 5 == 0:
            print(f"   Still waiting... ({i + 1}/{max_attempts})")

    print(f"❌ API did not respond after {max_attempts} attempts")
    print(f"\n🔍 Troubleshooting:")
    print(f"   1. Check if containers are running: docker-compose ps")
    print(f"   2. Check API logs: docker-compose logs booking-api --tail=20")
    print(f"   3. Try accessing manually: curl http://localhost:8000/health")
    return False


def create_event(num_seats=10):
    """Create a test event"""
    print(f"\n📅 Creating event with {num_seats} seats...")

    event_data = {
        "event_name": "Rock Concert 2025",
        "event_date": (datetime.now() + timedelta(days=30)).isoformat(),
        "venue": "Madison Square Garden",
        "total_seats": num_seats
    }

    try:
        print(f"   Sending POST to {BASE_URL}/events")
        print(f"   Data: {event_data}")

        response = requests.post(
            f"{BASE_URL}/events",
            json=event_data,
            timeout=10
        )

        print(f"   Response status: {response.status_code}")

        if response.status_code == 201:
            event = response.json()
            print(f"✅ Event created: {event['event_name']}")
            print(f"   Event ID: {event['event_id']}")
            print(f"   Total Seats: {event['total_seats']}")
            print(f"   Available Seats: {event['available_seats']}")
            return event['event_id']
        else:
            print(f"❌ Failed to create event")
            print(f"   Status: {response.status_code}")
            print(f"   Response: {response.text}")
            return None

    except Exception as e:
        print(f"❌ Exception creating event: {e}")
        return None


def create_seats(event_id, count=100):
    """Create seats for the event"""
    print(f"\n🪑 Creating {count} seats...")
    seat_ids = []

    # Create 10 rows (A-J) with 10 seats each
    rows = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J']
    seats_per_row = count // len(rows)

    created = 0
    failed = 0

    for row_idx, row in enumerate(rows):
        if created >= count:
            break

        for seat_num in range(1, seats_per_row + 1):
            if created >= count:
                break

            seat_number = f"{row}{seat_num}"

            # Determine seat type and price
            if row in ['A', 'B', 'C']:
                seat_type = "vip"
                price = 150.00
            elif row in ['D', 'E', 'F']:
                seat_type = "premium"
                price = 100.00
            else:
                seat_type = "standard"
                price = 50.00

            seat_data = {
                "seat_number": seat_number,
                "seat_type": seat_type,
                "price": price
            }

            try:
                response = requests.post(
                    f"{BASE_URL}/events/{event_id}/seats",
                    json=seat_data,
                    timeout=5
                )

                if response.status_code == 201:
                    seat = response.json()
                    seat_ids.append(seat['seat_id'])
                    created += 1

                    # Show progress every 10 seats
                    if created % 10 == 0:
                        print(f"   Created {created}/{count} seats...")
                else:
                    failed += 1
                    if failed <= 3:  # Only show first 3 failures
                        print(f"   ❌ Failed to create {seat_number}: {response.status_code}")

            except Exception as e:
                failed += 1
                if failed <= 3:
                    print(f"   ❌ Exception creating {seat_number}: {e}")

    print(f"✅ Created {len(seat_ids)} seats")
    if failed > 0:
        print(f"⚠️  {failed} seats failed to create")

    return seat_ids


def verify_data(event_id):
    """Verify the created data"""
    print(f"\n🔍 Verifying data...")

    try:
        # Get event
        event_response = requests.get(f"{BASE_URL}/events/{event_id}", timeout=5)
        event = event_response.json()

        # Get seats
        seats_response = requests.get(f"{BASE_URL}/events/{event_id}/seats", timeout=5)
        seats = seats_response.json()

        print(f"   Event total_seats: {event['total_seats']}")
        print(f"   Event available_seats: {event['available_seats']}")
        print(f"   Actual seats created: {len(seats)}")

        # Count by status
        available = sum(1 for s in seats if s['status'] == 'available')
        booked = sum(1 for s in seats if s['status'] == 'booked')

        print(f"   Seats by status:")
        print(f"     - Available: {available}")
        print(f"     - Booked: {booked}")

        if event['total_seats'] == len(seats):
            print(f"   ✅ Seat counts match!")
            return True
        else:
            print(f"   ⚠️  Mismatch detected")
            return False

    except Exception as e:
        print(f"   ❌ Verification failed: {e}")
        return False


def main():
    print("🚀 Starting data seeding...\n")
    print(f"Target API: {BASE_URL}\n")

    # Wait for API
    if not wait_for_api():
        print("\n💡 Make sure the API is running:")
        print("   docker-compose up -d")
        print("   docker-compose logs booking-api")
        sys.exit(1)

    # Create event with 100 seats
    num_seats = 100
    event_id = create_event(num_seats)
    if not event_id:
        print("\n❌ Failed to create event. Exiting.")
        sys.exit(1)

    # Create seats
    seat_ids = create_seats(event_id, count=num_seats)

    if not seat_ids:
        print("\n❌ No seats were created. Exiting.")
        sys.exit(1)

    # Verify
    verify_data(event_id)

    print("\n" + "=" * 70)
    print("✅ Data seeding complete!")
    print("=" * 70)
    print(f"\n📊 Summary:")
    print(f"   Event ID: {event_id}")
    print(f"   Seats created: {len(seat_ids)}")

    print(f"\n🔗 Quick Links:")
    print(f"   API Docs: {BASE_URL}/docs")
    print(f"   Health: {BASE_URL}/health")
    print(f"   Events: {BASE_URL}/events")
    print(f"   This Event: {BASE_URL}/events/{event_id}")
    print(f"   Event Seats: {BASE_URL}/events/{event_id}/seats")
    print(f"   Real-time UI: {BASE_URL}/realtime")

    print(f"\n💡 Test booking with PowerShell:")
    print(f"""
$bookingData = @{{
    user_id = "test-user-123"
    event_id = "{event_id}"
    seat_id = "{seat_ids[0]}"
    payment_method = "credit_card"
    card_number = "4242424242424242"
    cvv = "123"
    expiry_month = "12"
    expiry_year = "2026"
    card_holder = "John Doe"
}} | ConvertTo-Json

Invoke-RestMethod -Uri "{BASE_URL}/bookings" `
    -Method Post `
    -ContentType "application/json" `
    -Body $bookingData
    """)


if __name__ == "__main__":
    main()
